class BowlingGame:
    """Keeps track of the rolls in a game of bowling and computes its score."""

    def __init__(self):
        self._frames = []
        self._current_frame = []
        self._game_over = False

    def roll(self, pins):
        if self._game_over:
            raise Exception("Cannot roll after the game is over")
        if pins < 0 or pins > 10:
            raise Exception("Pin count must be between 0 and 10")

        frame = self._current_frame
        if len(frame) == 1 and frame[0] < 10 and frame[0] + pins > 10:
            raise Exception("Rolls in a frame cannot score more than 10 points")
        if len(frame) == 2 and frame[1] < 10 and frame[1] + pins > 10:
            raise Exception("Bonus rolls cannot score more than 10 points together")

        frame.append(pins)

        if self._frame_is_closed():
            self._frames.append(frame)
            self._current_frame = []
            if len(self._frames) == 10:
                self._game_over = True

    def score(self):
        if not self._game_over:
            raise Exception("Cannot score an incomplete game")

        rolls = []
        for frame in self._frames:
            rolls.extend(frame)

        total = 0
        i = 0
        for frame_number in range(10):
            if rolls[i] == 10:
                if frame_number == 9:
                    total += rolls[i] + rolls[i + 1] + rolls[i + 2]
                else:
                    total += 10 + rolls[i + 1] + rolls[i + 2]
                i += 1
            elif rolls[i] + rolls[i + 1] == 10:
                if frame_number == 9:
                    total += rolls[i] + rolls[i + 1] + rolls[i + 2]
                else:
                    total += 10 + rolls[i + 2]
                i += 2
            else:
                total += rolls[i] + rolls[i + 1]
                i += 2
        return total

    def _frame_is_closed(self):
        frame = self._current_frame
        if len(frame) == 1:
            # A strike closes the frame, except in the tenth frame
            # where it earns two bonus rolls.
            return frame[0] == 10 and len(self._frames) < 9
        if len(frame) == 2:
            if len(self._frames) < 9:
                return True
            # In the tenth frame only an open frame (less than 10)
            # closes here; a spare or strike earns bonus rolls.
            return sum(frame) < 10
        # Three or more rolls only occur in the tenth frame; it is done.
        return True

